@@ -2,6 +2,7 @@ package attacker

 import (
 	"context"
+	"sync"
 	"testing"
 	"time"

@@ -9,26 +10,88 @@ import (
 )

 func TestAttack(t *testing.T) {
-	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
+	ctx, cancel := context.WithCancel(context.Background())
 	defer cancel()
+
 	tests := []struct {
-		name   string
-		target string
-		opts   Options
-		want   *Metrics
+		name         string
+		target       string
+		opts         Options
+		want         *Metrics
+		wantResCount int
 	}{
 		{
 			name:   "no target given",
 			target: "",
 			want:   nil,
 		},
+		{
+			name:   "no result given back",
+			target: "http://host.xz",
+			opts: Options{
+				Attacker: &fakeAttacker{},
+			},
+			want: &Metrics{
+				StatusCodes: make(map[string]int),
+				Errors:      []string{},
+			},
+			wantResCount: 0,
+		},
+		/*{
+			name:   "two result given back",
+			target: "http://host.xz",
+			opts: Options{
+				Attacker: &fakeAttacker{
+					results: []*vegeta.Result{
+						{
+							Attack: "1",
+						},
+						{
+							Attack: "2",
+						},
+					},
+				},
+			},
+			want: &Metrics{
+				StatusCodes: make(map[string]int),
+				Errors:      []string{},
+			},
+			wantResCount: 2,
+		},*/
 	}

 	for _, tt := range tests {
-		tt.opts.Attacker = &fakeAttacker{}
+		ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
+		w := &watcher{
+			resCh: make(chan *Result),
+		}
+
+		var wg sync.WaitGroup
+		wg.Add(1)
+		go w.countRes(ctx, &wg)
 		t.Run(tt.name, func(t *testing.T) {
-			got := Attack(ctx, tt.target, make(chan *Result), tt.opts)
+			got := Attack(ctx, tt.target, w.resCh, tt.opts)
+			cancel()
+			wg.Wait()
 			assert.Equal(t, tt.want, got)
+			assert.Equal(t, tt.wantResCount, w.count)
 		})
 	}
 }
+
+type watcher struct {
+	resCh chan *Result
+	count int
+}
+
+func (w *watcher) countRes(ctx context.Context, wg *sync.WaitGroup) {
+	for {
+		select {
+		case <-ctx.Done():
+			wg.Done()
+			return
+		case <-w.resCh:
+			w.count++
+		}
+	}
+}
